import type {
  SplitIconButtonProps,
  SplitIconButtonLeadingProps,
  SplitIconButtonTrailingProps,
  SplitIconButtonMenuContentProps,
  SplitIconButtonMenuItemProps,
} from "./split-icon-button.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { ChevronDownSm } from "@exp-textura/icons";
import { Menu } from "@components/menu";
import { IconButton } from "@components/icon-button";

import { SplitIconButtonClasses, StyledSplitIconButton } from "./split-icon-button.styles";

const getSplitIconButtonChildren = (
  children: React.ReactNode,
): {
  leading: React.ReactElement | null;
  trailing: React.ReactElement | null;
  menuContent: React.ReactElement | null;
} => {
  let leading: React.ReactElement | null = null;
  let trailing: React.ReactElement | null = null;
  let menuContent: React.ReactElement | null = null;

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;
      if (displayName === SplitIconButtonLeading.displayName) {
        leading = child;
      } else if (displayName === SplitIconButtonTrailing.displayName) {
        trailing = child;
      } else if (displayName === SplitIconButtonMenuContent.displayName) {
        menuContent = child;
      }
    }
  });

  return { leading, trailing, menuContent };
};

const SplitIconButtonRoot = forwardRef<HTMLDivElement, SplitIconButtonProps>(
  (
    {
      children,
      className,
      variant = "default",
      size = "default",
      disabled = false,
      side = "bottom",
      sideOffset = 4,
      align = "end",
      alignOffset = 0,
      menuVariant,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SplitIconButtonClasses.root, className, {
      [SplitIconButtonClasses.sm]: size === "sm",
    });

    const { leading, trailing, menuContent } = getSplitIconButtonChildren(children);

    if (!leading && !trailing && !menuContent) {
      return null;
    }

    const leadingWithProps =
      leading &&
      React.cloneElement(leading, {
        variant,
        buttonType: leading.props.buttonType || "secondary",
        size: leading.props.size || size,
        disabled: disabled || leading.props.disabled,
        className: clsx(SplitIconButtonClasses.leading, leading.props.className),
      });

    const trailingWithProps =
      trailing &&
      React.cloneElement(trailing, {
        variant,
        buttonType: trailing.props.buttonType || "secondary",
        size: trailing.props.size || "sm",
        disabled: disabled || trailing.props.disabled,
        className: clsx(SplitIconButtonClasses.trailing, trailing.props.className),
      });

    const menuContentWithProps = menuContent && <Menu.Content {...menuContent.props} />;

    return (
      <StyledSplitIconButton
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {leadingWithProps}
        <Menu
          align={align}
          alignOffset={alignOffset}
          side={side}
          sideOffset={sideOffset}
          variant={menuVariant || "icons-only"}
        >
          <Menu.Trigger>{trailingWithProps}</Menu.Trigger>
          {menuContentWithProps}
        </Menu>
      </StyledSplitIconButton>
    );
  },
);
SplitIconButtonRoot.displayName = "SplitIconButton";

const SplitIconButtonLeading = forwardRef<HTMLButtonElement, SplitIconButtonLeadingProps>(
  ({ children, ...props }, ref) => {
    return (
      <IconButton ref={ref} {...props}>
        {children}
      </IconButton>
    );
  },
);
SplitIconButtonLeading.displayName = "SplitIconButton.Leading";

const SplitIconButtonTrailing = forwardRef<HTMLButtonElement, SplitIconButtonTrailingProps>(
  ({ children, "aria-label": ariaLabel, ...props }, ref) => {
    return (
      <IconButton ref={ref} aria-label={ariaLabel || "More actions"} size="sm" {...props}>
        {children || <ChevronDownSm />}
      </IconButton>
    );
  },
);
SplitIconButtonTrailing.displayName = "SplitIconButton.Trailing";

const SplitIconButtonMenuContent = (props: SplitIconButtonMenuContentProps) => {
  // Placeholder wrapper for menu content props. Rendering happens in SplitIconButtonRoot.
  return <>{props.children}</>;
};
SplitIconButtonMenuContent.displayName = "SplitIconButton.MenuContent";

const SplitIconButtonMenuItem = forwardRef<HTMLDivElement, SplitIconButtonMenuItemProps>(
  ({ children, ...props }, ref) => {
    return (
      <Menu.Item ref={ref} {...props}>
        {children}
      </Menu.Item>
    );
  },
);
SplitIconButtonMenuItem.displayName = "SplitIconButton.MenuItem";

const SplitIconButton = Object.assign(SplitIconButtonRoot, {
  Leading: SplitIconButtonLeading,
  Trailing: SplitIconButtonTrailing,
  MenuContent: SplitIconButtonMenuContent,
  MenuItem: SplitIconButtonMenuItem,
});

export default SplitIconButton;
